import React, { useEffect } from 'react';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchIncidentDetections,
  fetchIncidentDetectionStats,
  setFilters,
  setPage,
} from '../../store/slices/incidentDetectionsSlice';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import { useResponsive } from '../../hooks/useResponsive';
import { useFormOptions } from '../../hooks/useFormOptions';
import { useIncidentDetectionPermissions } from '../../hooks/useIncidentDetectionPermissions';
import { DetectionStatsCards } from './components/DetectionStatsCards';
import { DetectionFiltersBar } from './components/DetectionFiltersBar';
import { DetectionTable } from './components/DetectionTable';
import { IncidentDetection, IncidentDetectionFilters } from '../../models/IncidentDetection';
import styles from './IncidentDetectionListPage.module.css';
import { Button, TableCard, Pagination } from '@linm-soft-org/linm-web-common-components';
import { ErpFilterCardHeader } from '../../components/layout/ErpFilterCardHeader';

const IncidentDetectionListPage: React.FC = () => {
  const appNavigate = useAppNavigate();
  const dispatch = useAppDispatch();
  const { isMobile } = useResponsive();
  const { detectionLabel: L, detectionStatusOptions } = useFormOptions('detection-list');
  const { canCreate } = useIncidentDetectionPermissions();

  const { items, loading, filters, pagination, stats } = useAppSelector((s) => s.incidentDetections);
  const showLoading = useMinLoadingTime(loading);

  const statusLabel = (status: string) =>
    detectionStatusOptions.find((o) => o.value === status)?.label ?? status;

  useEffect(() => {
    const t = setTimeout(() => { dispatch(fetchIncidentDetections()); }, 0);
    return () => clearTimeout(t);
  }, [dispatch, filters, pagination.page]);

  useEffect(() => {
    const t = setTimeout(() => { dispatch(fetchIncidentDetectionStats()); }, 0);
    return () => clearTimeout(t);
  }, [dispatch]);

  const handleFilterChange = (f: IncidentDetectionFilters) => {
    dispatch(setFilters(f));
    dispatch(setPage(1));
  };

  const handleClearFilters = () => {
    dispatch(setFilters({}));
    dispatch(setPage(1));
  };

  const handleCreate = () => appNavigate(scykRoutes.detections.new);
  const handleView = (item: IncidentDetection) =>
    appNavigate(scykRoutes.detections.detail(item.id));

  return (
    <div className={styles.page} data-catalog-list-page data-lin-list-layout="erp-filter-bar">
      <div className={styles.pageHeader}>
        <h1 className={styles.title}>
          <i className="fas fa-camera" />
          {!isMobile && ` ${L('pageTitle')}`}
        </h1>
        <div className={styles.headerActions}>
          {canCreate && (
            <Button variant="primary" onClick={handleCreate} data-testid="incident-detection-create">
              <i className="fas fa-plus" />
              {!isMobile && ` ${L('create')}`}
            </Button>
          )}
        </div>
      </div>

      <DetectionStatsCards stats={stats} loading={showLoading} label={L} statusLabel={statusLabel} />

      <TableCard
        header={
          <ErpFilterCardHeader title={L('listCard')} testIdPrefix="incident-detection">
            <DetectionFiltersBar
              filters={filters}
              onChange={handleFilterChange}
              onClear={handleClearFilters}
              loading={showLoading}
            />
          </ErpFilterCardHeader>
        }
        footer={
          <Pagination
            currentPage={pagination.page}
            totalPages={Math.ceil(Math.max(pagination.totalCount, 1) / pagination.pageSize)}
            totalCount={pagination.totalCount}
            pageSize={pagination.pageSize}
            onPageChange={(p) => dispatch(setPage(p))}
          />
        }
      >
        <DetectionTable
          items={items}
          loading={showLoading}
          onView={handleView}
          label={L}
          statusLabel={statusLabel}
        />
      </TableCard>
    </div>
  );
};

export default IncidentDetectionListPage;
