import React from 'react';
import { IncidentDetectionStats } from '../../../models/IncidentDetection';
import { StatsCardsGrid, StatsCard } from '@linm-soft-org/linm-web-common-components';

interface Props {
  stats: IncidentDetectionStats;
  loading?: boolean;
  label: (key: string) => string;
  statusLabel: (status: string) => string;
}

export const DetectionStatsCards: React.FC<Props> = ({ stats, loading, label, statusLabel }) => (
  <StatsCardsGrid>
    <StatsCard label={label('statsTotal')} value={stats.total} icon="fas fa-camera" variant="primary" loading={loading} />
    <StatsCard label={statusLabel('draft')} value={stats.draft} icon="fas fa-file-alt" variant="gray" loading={loading} />
    <StatsCard label={statusLabel('routed')} value={stats.routed} icon="fas fa-paper-plane" variant="warning" loading={loading} />
    <StatsCard label={statusLabel('claimed')} value={stats.claimed} icon="fas fa-hand-paper" variant="primary" loading={loading} />
    <StatsCard label={statusLabel('converted')} value={stats.converted} icon="fas fa-check-circle" variant="success" loading={loading} />
  </StatsCardsGrid>
);
