import type { MedicalIncidentAttachment } from './MedicalIncident';

export const IncidentDetectionStatus = {
  Draft: 'draft',
  Routed: 'routed',
  Claimed: 'claimed',
  Converted: 'converted',
  Rejected: 'rejected',
  Cancelled: 'cancelled',
} as const;

export type IncidentDetectionStatusValue =
  (typeof IncidentDetectionStatus)[keyof typeof IncidentDetectionStatus];

export interface IncidentDetection {
  id: string;
  idCode: string;
  description: string;
  detectedAt: string;
  locationText: string | null;
  status: IncidentDetectionStatusValue;
  targetDepartmentId: string;
  targetDepartmentName: string;
  detectorUserId: string;
  detectorUserName: string;
  detectorDepartmentId: string | null;
  detectorDepartmentName: string | null;
  claimedById: string | null;
  claimedByName: string | null;
  claimedAt: string | null;
  incidentId: string | null;
  rejectReason: string | null;
  createdAt: string;
  updatedAt: string;
  attachments: MedicalIncidentAttachment[];
}

export interface IncidentDetectionFilters {
  search?: string;
  status?: IncidentDetectionStatusValue | '';
  inbox?: 'mine' | 'department' | '';
  targetDepartmentId?: string;
}

export interface IncidentDetectionStats {
  total: number;
  draft: number;
  routed: number;
  claimed: number;
  converted: number;
  rejected: number;
}

export function createEmptyIncidentDetection(): Partial<IncidentDetection> {
  return {
    description: '',
    detectedAt: new Date().toISOString(),
    locationText: '',
    status: IncidentDetectionStatus.Draft,
    targetDepartmentId: '',
    targetDepartmentName: '',
    attachments: [],
  };
}
