import React, { useEffect, useMemo, useState } from 'react';
import { IncidentDetectionFilters } from '../../../models/IncidentDetection';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './DetectionFiltersBar.module.css';
import {
  LinErpListFilterBar,
  SearchTextInput,
  Select,
} from '@linm-soft-org/linm-web-common-components';

const TEST_ID_PREFIX = 'incident-detection';

interface Props {
  filters: IncidentDetectionFilters;
  onChange: (f: IncidentDetectionFilters) => void;
  onClear: () => void;
  loading?: boolean;
}

export const DetectionFiltersBar: React.FC<Props> = ({
  filters,
  onChange,
  onClear,
  loading = false,
}) => {
  const [draft, setDraft] = useState<IncidentDetectionFilters>(filters);
  const {
    departmentOptions,
    detectionStatusOptions,
    detectionInboxOptions,
    detectionLabel: L,
  } = useFormOptions('detection-list');

  useEffect(() => {
    setDraft(filters);
  }, [filters]);

  const statusOptions = useMemo(
    () => [{ value: '', label: L('allStatus') }, ...detectionStatusOptions],
    [detectionStatusOptions, L],
  );

  const deptOptions = useMemo(
    () => [{ value: '', label: L('allDept') }, ...departmentOptions],
    [departmentOptions, L],
  );

  const hasActiveFilters = !!(draft.search || draft.status || draft.inbox || draft.targetDepartmentId);

  const handleSearch = () => {
    onChange({
      search: draft.search?.trim() || undefined,
      status: draft.status || undefined,
      inbox: draft.inbox || undefined,
      targetDepartmentId: draft.targetDepartmentId || undefined,
    });
  };

  const handleClear = () => {
    setDraft({});
    onClear();
  };

  return (
    <LinErpListFilterBar
      testIdPrefix={TEST_ID_PREFIX}
      onSearch={handleSearch}
      loading={loading}
      leading={(
        <>
          <div data-testid={`${TEST_ID_PREFIX}-field-search`}>
            <SearchTextInput
              label={L('search')}
              placeholder={L('searchPlaceholder')}
              value={draft.search ?? ''}
              onChange={(search) => setDraft((prev) => ({ ...prev, search }))}
              testId={`${TEST_ID_PREFIX}-search-text`}
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-inbox`}>
            <Select
              label={L('inbox')}
              options={detectionInboxOptions}
              value={draft.inbox ?? ''}
              onChange={(e) =>
                setDraft((prev) => ({
                  ...prev,
                  inbox: e.target.value as IncidentDetectionFilters['inbox'],
                }))
              }
              size="small"
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-status`}>
            <Select
              label={L('status')}
              options={statusOptions}
              value={draft.status ?? ''}
              onChange={(e) =>
                setDraft((prev) => ({
                  ...prev,
                  status: e.target.value as IncidentDetectionFilters['status'],
                }))
              }
              size="small"
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-department`}>
            <Select
              label={L('targetDepartment')}
              options={deptOptions}
              value={draft.targetDepartmentId ?? ''}
              onChange={(e) =>
                setDraft((prev) => ({ ...prev, targetDepartmentId: e.target.value }))
              }
              size="small"
            />
          </div>
          {hasActiveFilters && (
            <div data-testid={`${TEST_ID_PREFIX}-field-clear`}>
              <button
                className={styles.clearFiltersButton}
                onClick={handleClear}
                type="button"
                title={L('clearFilters')}
              >
                <i className="fas fa-times-circle" />
                <span>{L('clearFilters')}</span>
              </button>
            </div>
          )}
        </>
      )}
    />
  );
};
